-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.frame_jetty_over(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case when exists (select 1 from floor_tile f
                            where f.world_id = p_world and f.level = outside_stair_level()::int
                              and f.x = p_x and f.y = p_y and f.kind = 'stairs')
              then b.name || ' outside staircase on that tile.'
              else 'Under ' || b.name || ' jetty.' end
    from building b
   where b.world_id = p_world and b.id = frame_jetty_of(p_world, p_x, p_y)
$function$
